# ------------------------------------------------------------------------------------------------
# F04 conditional branch plus missing condition
# ------------------------------------------------------------------------------------------------
GROUPS = [("older-people", "POPULATION", "older people"), ("interacting-drugs", "CO_INTERVENTION", "people taking drugs that interact with lithium"),
          ("renal-thyroid-risk", "CONDITION_PRESENT", "people who are at risk of impaired renal or thyroid function, raised calcium levels or other complications"),
          ("poor-symptom-control", "CONDITION_PRESENT", "people who have poor symptom control"),
          ("poor-adherence", "POPULATION", "people with poor adherence"),
          ("last-level-gte-0.8", "MEASUREMENT_THRESHOLD", "people whose last plasma lithium level was 0.8 mmol per litre or higher")]

EVAL_QUERY = """MATCH (e:ProtocolEdition {uid: $e})-[:HAS_PROTOCOL_STEP]->(s:ProtocolStep {requirementLevel: 'CONDITIONAL'})
MATCH (s)-[r:HAS_CONSTRAINT {constraintRole: 'APPLIES_WHEN'}]->(c:Constraint)
WITH s, coalesce(r.conditionGroup, c.uid) AS grp,
     CASE WHEN c.uid IN $trueFacts THEN (CASE WHEN coalesce(r.negated, false) THEN false ELSE true END)
          WHEN c.uid IN $falseFacts THEN (CASE WHEN coalesce(r.negated, false) THEN true ELSE false END)
          ELSE null END AS lit, c.uid AS cuid
WITH s, grp, collect({v: lit}) AS litMaps, collect(CASE WHEN lit IS NULL THEN cuid END) AS unknownFacts
WITH s, grp, [m IN litMaps | m.v] AS lits, unknownFacts
WITH s, unknownFacts, CASE WHEN any(x IN lits WHERE x = true) THEN 'T' WHEN all(x IN lits WHERE x = false) THEN 'F' ELSE 'U' END AS g
WITH s, collect(g) AS groups, [u IN collect(unknownFacts) | u] AS uf
RETURN s.stepKey AS stepKey,
       CASE WHEN 'F' IN groups THEN 'DOES_NOT_APPLY' WHEN all(x IN groups WHERE x = 'T') THEN 'APPLIES' ELSE 'UNKNOWN_MISSING_FACT' END AS applicability,
       reduce(acc = [], l IN uf | acc + l) AS missingFactConstraintUids
ORDER BY stepKey"""

