# ------------------------------------------------------------------------------------------------
# F13 subprotocol edition binding (pinned vs floating)
# ------------------------------------------------------------------------------------------------
def f13():
    fx = Fx("13", hdr("13", "component/subprotocol relations with the edition-binding rule (PINNED INCLUDES_PROTOCOL vs FLOATING HAS_SUBPROTOCOL)",
                      "W16-S04/S05 protocols.io PBMC CPT V.1/V.2 (real versions and dates); SYNTHETIC parent workflows"))
    SP = "hu:protocol:protocolsio-pbmc-cpt"
    fx.node("Protocol", SP, {"name": "PBMCs isolation from CPT tube", "protocolType": "SAMPLE_COLLECTION_PROTOCOL"})
    for v, d, vt in [("v1", "2020-08-06", "2022-07-27"), ("v2", "2022-07-27", None)]:
        fx.source(f"hu:source:protocolsio-pbmc-cpt-{v}", f"https://www.protocols.io/view/pbmcs-isolation-from-cpt-tube-kxygxeqr4v8j/{v}", f"PBMCs isolation from CPT tube {v.upper()}",
                  "STANDARDS_DOCUMENT", f"hu:snapshot:protocolsio-pbmc-cpt-{v}-2026-10-04", "2026-10-04T01:05:00Z", "2026-10-04T01:05:00Z", "PARTIAL_EXCERPT",
                  f"hu:locator:protocolsio-pbmc-cpt-{v}-header", ("SECTION", "Version header"))
        fx.node("ProtocolEdition", f"hu:protocol-edition:protocolsio-pbmc-cpt-{v}", {"editionLabel": "V." + v[1], "changeProvenance": "SOURCE_VERSIONED", "payloadHash": sha(v),
                "sourceVersionDate": D(d)})
        attach(fx, SP, f"hu:protocol-edition:protocolsio-pbmc-cpt-{v}", f"hu:assertion:protocolsio-pbmc-cpt-has-{v}", f"hu:rel:protocolsio-pbmc-cpt-{v}",
               f"hu:locator:protocolsio-pbmc-cpt-{v}-header", DT(d + "T00:00:00Z"), "DAY", "STATED_BY_SOURCE",
               DT(vt + "T00:00:00Z") if vt else None, "DAY" if vt else None, "INFERRED" if vt else "UNKNOWN")
    fx.node("Protocol", "hu:protocol:synthetic-pinned-parent-workflow", {"name": "SYNTHETIC cohort sample workflow (pins PBMC V.2)", "protocolType": "WORKFLOW"})
    fx.node("Protocol", "hu:protocol:synthetic-floating-parent-workflow", {"name": "SYNTHETIC cohort sample workflow (links PBMC protocol without version)", "protocolType": "WORKFLOW"})
    fx.node("ProtocolEdition", "hu:protocol-edition:synthetic-pinned-parent-e1", {"editionLabel": "v1", "changeProvenance": "SOURCE_VERSIONED", "payloadHash": sha("pinned-parent")})
    fx.node("ProtocolEdition", "hu:protocol-edition:synthetic-floating-parent-e1", {"editionLabel": "v1", "changeProvenance": "SOURCE_VERSIONED", "payloadHash": sha("floating-parent")})
    fx.edge("ProtocolEdition", "hu:protocol-edition:synthetic-pinned-parent-e1", "INCLUDES_PROTOCOL", "ProtocolEdition", "hu:protocol-edition:protocolsio-pbmc-cpt-v2", {"orderIndex": 2})
    fx.edge("ProtocolEdition", "hu:protocol-edition:synthetic-floating-parent-e1", "HAS_SUBPROTOCOL", "Protocol", SP, {"orderIndex": 2})
    fx.c("Q-W16-13: which subprotocol edition does each parent include at a valid-time instant V (2021-06-01 and 2023-06-01)? PINNED is fixed; FLOATING is resolved as-of\n"
         "with the QS-2b validity classes and labelled RESOLVED_AS_OF.")
    fx.raw("""UNWIND [datetime('2021-06-01T00:00:00Z'), datetime('2023-06-01T00:00:00Z')] AS V
MATCH (pe:ProtocolEdition) WHERE pe.uid IN ['hu:protocol-edition:synthetic-pinned-parent-e1', 'hu:protocol-edition:synthetic-floating-parent-e1']
OPTIONAL MATCH (pe)-[:INCLUDES_PROTOCOL]->(pinned:ProtocolEdition)
OPTIONAL MATCH (pe)-[:HAS_SUBPROTOCOL]->(sp:Protocol)-[h:HAS_PROTOCOL_EDITION]->(fe:ProtocolEdition)
WHERE h.recordedTo IS NULL AND (h.validFrom IS NULL OR h.validFrom <= V) AND (h.validTo IS NULL OR V < h.validTo)
RETURN pe.uid AS parentEdition, toString(date(V)) AS validAt,
       CASE WHEN pinned IS NOT NULL THEN 'PINNED' WHEN fe IS NOT NULL THEN 'RESOLVED_AS_OF' ELSE 'UNRESOLVED' END AS binding,
       coalesce(pinned.editionLabel, fe.editionLabel) AS includedEdition,
       CASE WHEN fe IS NOT NULL AND h.validTo IS NULL THEN 'OPEN_END_UNVERIFIED' WHEN fe IS NOT NULL THEN 'KNOWN_WITHIN' END AS validityClass
ORDER BY parentEdition, validAt""")
    fx.write(f"{OUT}/13-subprotocol-edition-binding.cypher")

for f in (f01, f02, f03, f04, f05, f06, f07, f08, f09, f10, f11, f12, f13): f()
